import{_ as l,r as t,o as c,c as i,e,a,d as s,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"内容块 - October CMS - 3.x","titleTemplate":false,"description":"用于存储和更新页面内容的专用文件。","frontmatter":{"subtitle":"用于存储和更新页面内容的专用文件。"},"headers":[{"level":2,"title":"介绍","slug":"介绍","link":"#介绍","children":[]},{"level":2,"title":"渲染内容块","slug":"渲染内容块","link":"#渲染内容块","children":[]},{"level":2,"title":"向内容块传递变量","slug":"向内容块传递变量","link":"#向内容块传递变量","children":[{"level":3,"title":"全局变量","slug":"全局变量","link":"#全局变量","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}]}],"relativePath":"3.x/zh-cn/cms/themes/content.md","filePath":"3.x/zh-cn/cms/themes/content.md"}'),d={name:"3.x/zh-cn/cms/themes/content.md"};function u(g,n,k,h,m,v){const o=t("pre-heading"),p=t("post-heading");return c(),i("div",null,[e(o),n[0]||(n[0]=a("h1",null,"内容块",-1)),e(p),n[1]||(n[1]=a("p",null,[s("内容块可以是文本、HTML 或 "),a("a",{href:"http://daringfireball.net/projects/markdown/syntax",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("Markdown"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),a("span",{class:"sr-only"},"(opens new window)")])]),s(" 块，它们与页面或布局分开编辑。内容块设计用于保存静态内容，并支持基本的模板变量。"),a("a",{href:"./partials.html"},"部件"),s("更加灵活，应该用于生成动态内容。")],-1)),n[2]||(n[2]=r(`<h2 id="介绍"><a href="#介绍" class="header-anchor">#</a> 介绍</h2><p>内容块文件存放在主题目录的 <strong>/content</strong> 子目录中。内容文件支持以下扩展名。</p><div class="table"><table tabindex="0"><thead><tr><th>扩展名</th><th>描述</th></tr></thead><tbody><tr><td><strong>html</strong></td><td>用于 HTML 标记（所见即所得编辑器）。</td></tr><tr><td><strong>htm</strong></td><td>用于 HTML 标记（代码编辑器）。</td></tr><tr><td><strong>txt</strong></td><td>用于纯文本。</td></tr><tr><td><strong>md</strong></td><td>用于 Markdown 语法。</td></tr></tbody></table></div><p>扩展名会影响内容块在后端用户界面中的显示模式，可以是所见即所得编辑器、代码编辑器或 Markdown 编辑器。它还决定了在网站上渲染块的方式；例如，Markdown 块会在显示之前转换为 HTML。</p><h2 id="渲染内容块"><a href="#渲染内容块" class="header-anchor">#</a> 渲染内容块</h2><p>使用 <code>{% content &#39;file.htm&#39; %}</code> 标签在<a href="./pages.html">页面</a>、<a href="./partials.html">部件</a>或<a href="./layouts.html">布局</a>中渲染内容块。</p><p>此示例展示了一个渲染内容块的完整页面。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/contacts</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>contacts<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>contacts.html<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>另一个使用 <code>md</code> 扩展名渲染 Markdown 的示例。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>my-markdown.md<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="向内容块传递变量"><a href="#向内容块传递变量" class="header-anchor">#</a> 向内容块传递变量</h2><p>有时您可能需要从外部代码向内容块传递变量。虽然内容块不支持 Twig 标记，但它们支持使用基本语法的变量。您可以通过在 <code>{% content %}</code> 标签中的内容块名称后面指定变量来向内容块传递变量。</p><p>向内容块传递一个名为 <code>name</code>、值为 <strong>John</strong> 的变量。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span> name<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>John<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>在内容块内部，可以使用单个<em>花括号</em>来访问变量。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>This is a demo for {name}<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>更多关于变量使用的信息可以在<a href="./../../markup/tag/content.html">标记指南</a>中找到。</p></div><h3 id="全局变量"><a href="#全局变量" class="header-anchor">#</a> 全局变量</h3><p>您可以使用 <code>View::share</code> 方法注册对所有内容块全局可用的变量。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">share</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;October CMS&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>放置此方法的常见位置是<a href="./../../extend/system/plugins.html">插件注册文件</a>的 register 或 boot 方法中。使用上面的示例，变量 <code>{site_name}</code> 将在所有内容块中可用。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Welcome to {site_name}<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../../markup/tag/content.html">Content Twig 标签</a></li></ul></div>`,24))])}const _=l(d,[["render",u]]);export{f as __pageData,_ as default};
